ui.css:
.hud { font-family: 'Pixelify Sans', system-ui, sans-serif; color: #f4e6ff; }
.panel { background: linear-gradient(90deg, rgba(22,12,42,.72), rgba(22,12,42,.25)); border-left: 2px solid #e8b85a; border-radius: 2px 18px 18px 2px; padding: 6px 14px 6px 8px; }
.bar { position: relative; height: 12px; border-radius: 2px; background: rgba(18,8,30,.85); border: 1px solid rgba(232,184,90,.7); box-shadow: 0 0 0 1px rgba(10,5,20,.8); }
.bar::before, .bar::after { content: ''; position: absolute; top: 50%; width: 9px; height: 9px; background: #e8b85a; transform: translateY(-50%) rotate(45deg); box-shadow: 0 0 8px rgba(255,200,120,.7); }
.bar::before { left: -6px; } .bar::after { right: -6px; }
.bar.hp > i { display: block; height: 100%; background: linear-gradient(#ffb36a 0%, #f07a3a 40%, #c2402c 100%); box-shadow: 0 0 10px rgba(255,120,60,.6), inset 0 1px 0 rgba(255,236,190,.6); }
.bar.xp > i { display: block; height: 100%; background: linear-gradient(90deg, #3fb0ae 0%, #7ee0cc 45%, #ffd08a 85%, #fff2c4 100%); box-shadow: 0 0 12px rgba(126,224,204,.55), inset 0 -3px 0 rgba(20,60,80,.35), inset 0 1px 0 rgba(255,255,255,.45); }
.title { font-family: 'Cinzel', serif; font-weight: 900; color: #fff2c4; letter-spacing: 6px; text-shadow: 0 0 22px rgba(255,170,90,.75), 0 3px 0 #2a1238; }
.label { font-family: 'Cinzel', serif; font-weight: 700; font-size: 10px; color: #e8b85a; letter-spacing: 4px; border-top: 1px solid rgba(232,184,90,.55); padding-top: 3px; }
.card { background: linear-gradient(180deg, rgba(48,28,82,.94) 0%, rgba(26,16,50,.96) 60%, rgba(18,30,46,.96) 100%); border: 1px solid #e8b85a; border-radius: 4px; box-shadow: 0 0 0 4px rgba(20,10,34,.85), 0 0 0 5px rgba(232,184,90,.35), 0 14px 30px rgba(0,0,0,.5), inset 0 0 30px rgba(126,224,204,.08); }
